import {escapeHTML as e} from './core.js?v=20261014h';
export function accountPage(space){const i=space.info();return `<div class="page-heading"><div><div class="eyebrow">MY STUDY SPACE</div><h1>ข้อมูลและเปิดบนอีกเครื่อง</h1><p>เปิดแอปแล้วเรียนได้เลย โน้ต รูปภาพ และความคืบหน้าบันทึกใน Supabase</p></div></div><section class="panel account-panel"><div class="notebook-status"><span class="status-dot"></span><strong data-sync-status>${e(i.status)}</strong></div><h2>ข้อมูลชุดเดียวกัน ทุกเครื่อง</h2><p>คัดลอกลิงก์ส่วนตัวด้านล่าง แล้วเปิดบนมือถือหรือคอมพิวเตอร์อีกเครื่องเพื่อใช้สมุดจดและความคืบหน้าชุดเดิม จากนั้นบันทึกลิงก์เป็นรายการโปรดได้</p><div class="button-row"><button class="button primary" data-action="account-copy-link">คัดลอกลิงก์เปิดบนอีกเครื่อง</button><button class="button secondary" data-action="account-sync">บันทึกและซิงก์ตอนนี้</button><button class="button secondary" data-action="account-reload">ลองเชื่อมต่ออีกครั้ง</button></div><p class="quiet-note">ลิงก์นี้เปิดข้อมูลส่วนตัวของคุณได้ เก็บไว้ใช้เอง หากเปิดลิงก์แอปทั่วไปในเครื่องใหม่ ระบบจะสร้างพื้นที่ใหม่ ให้ใช้ลิงก์ส่วนตัวเพื่อเปิดข้อมูลชุดเดิม</p><p>ซิงก์ล่าสุด: <span id="last-sync">${i.lastSync?e(new Date(i.lastSync).toLocaleString('th-TH')):'ยังไม่มี'}</span></p><p id="account-message" role="status" class="account-message"></p><div id="personal-link-fallback" hidden><label class="field">คัดลอกลิงก์นี้<input id="personal-link-value" readonly aria-label="ลิงก์ส่วนตัว"></label></div><div id="sync-conflict" ${i.conflict?'':'hidden'} class="notice danger"><h3>มีข้อมูลใหม่จากอีกเครื่อง</h3><p>เลือกฉบับที่จะใช้ ระบบจะเก็บทั้งสองฉบับไว้ก่อนแทนที่</p><div class="button-row"><button class="button secondary" data-action="account-remote">ใช้ฉบับคลาวด์</button><button class="button secondary" data-action="account-local">ใช้ฉบับเครื่องนี้</button></div></div></section><section class="panel"><h2>นำข้อมูลเดิมมาใช้</h2><p>หากเคยจดก่อนเปิดระบบออนไลน์ สามารถนำข้อมูลเดิมของเครื่องนี้มาใช้ หรือส่งออกไฟล์สำรองเพิ่มเติมได้</p><div class="button-row"><button class="button secondary" data-action="account-import-guest">นำข้อมูลเดิมของเครื่องนี้มาใช้</button><a class="button secondary" href="#settings">ตั้งค่าและสำรองข้อมูล</a></div></section>`;}
export async function accountAction(action,space,render,toast){
 const msg=document.getElementById('account-message');const say=t=>{if(msg)msg.textContent=t;};
 try{
  if(action==='account-reload'){location.reload();return;}
  if(action==='account-copy-link'){
   const access=space.access();if(!access?.url)throw Error('กำลังเตรียมลิงก์ส่วนตัว กรุณาลองอีกครั้ง');
   try{if(!navigator.clipboard?.writeText)throw Error('clipboard');await navigator.clipboard.writeText(access.url);say('คัดลอกแล้ว เปิดลิงก์นี้บนอีกเครื่องเพื่อใช้ข้อมูลชุดเดิม');toast('คัดลอกลิงก์ส่วนตัวแล้ว');}
   catch{document.getElementById('personal-link-fallback').hidden=false;const input=document.getElementById('personal-link-value');input.value=access.url;input.focus();input.select?.();say('คัดลอกลิงก์จากช่องด้านล่างได้เลย');}
   return;
  }
  if(action==='account-sync'){await space.sync();say(space.info().status);}
  if(action==='account-import-guest'&&confirm('แทนที่ข้อมูลพื้นที่นี้ด้วยข้อมูลเดิมของเครื่องนี้? แนะนำส่งออกสำรองก่อน'))await space.importGuest();
  if(['account-remote','account-local'].includes(action)&&confirm('ยืนยันใช้ฉบับที่เลือก? อีกฉบับจะเก็บเป็นสำเนากู้คืน')){await space.resolve(action==='account-local');render();}
 }catch(err){const text=err.message||'ดำเนินการไม่สำเร็จ';say(text);toast(text);}
}
